"use client"

import * as React from "react"
import { toast } from "sonner"

import {
  Alert,
  AlertAction,
  AlertDescription,
  AlertTitle,
} from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Field, FieldGroup, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemTitle,
} from "@/components/ui/item"
import { Textarea } from "@/components/ui/textarea"
import { EditorHeader } from "@/components/mockups/config-versioning/editor-header"
import { HistoryDrawer } from "@/components/mockups/config-versioning/history-drawer"
import { BackToNewestIcon } from "@/components/mockups/config-versioning/icons"
import { SaveReview } from "@/components/mockups/config-versioning/save-review"
import {
  type CaseId,
  RIVAL,
  type Subject,
  type Version,
} from "@/lib/mockups/config-versioning-data"

/**
 * The editor for anything versioned — a scenario's Scenario tab, or the
 * global prompt — cut to what DES-202 changes.
 *
 *  - Save makes a version. Live or not, the save review says what the save
 *    does to callers (save-review.tsx).
 *  - On a live item with saves ahead of the marker, one row under the header
 *    says which versions are not live and offers Review and publish. It is
 *    the ticket's draft indicator, unpublished state and publish action in
 *    one place, and it is absent when there is nothing to publish.
 *  - History (history-drawer.tsx) is where publishing, rolling back and
 *    "edit from here" happen, with the comparison on screen.
 *  - Edit from here opens an earlier version as the starting point, says so
 *    above the fields, and saves as a new version on top (PRD).
 */
export function VersionedEditor({
  initial,
  caseId,
}: {
  initial: Subject
  caseId: CaseId
}) {
  const [subject, setSubject] = React.useState(initial)
  const [base, setBase] = React.useState(initial.versions[0].n)
  const [draft, setDraft] = React.useState(initial.versions[0].body)
  const [reviewing, setReviewing] = React.useState(false)
  const [history, setHistory] = React.useState<{
    n: number
    against: number | null
  } | null>(null)
  const [rival, setRival] = React.useState<Version | null>(null)

  const canEdit = caseId !== "view-only"
  const newest = subject.versions[0]
  const baseVersion =
    subject.versions.find((version) => version.n === base) ?? newest
  const editingFrom = base !== newest.n && !rival
  const changes = subject.fields.filter(
    (field) => draft[field.id] !== newest.body[field.id],
  ).length
  const live = subject.marker !== null
  const ahead = live
    ? subject.versions.filter((v) => v.n > subject.marker!)
    : []

  /* A summary for a fresh save arrives a moment later (PRD: generation never
     blocks the save). In the pending case it never does. */
  React.useEffect(() => {
    if (caseId === "summary-pending") return
    if (newest.summary !== null) return
    const timer = setTimeout(
      () =>
        setSubject((current) => ({
          ...current,
          versions: current.versions.map((version) =>
            version.summary === null
              ? { ...version, summary: summarise(current, version) }
              : version,
          ),
        })),
      2500,
    )
    return () => clearTimeout(timer)
  }, [caseId, newest.summary])

  function openReview() {
    /* The conflict case: someone else's save lands after this page opened. */
    if (caseId === "conflict" && !rival) {
      const theirs: Version = {
        ...RIVAL,
        n: newest.n + 1,
        editedFrom: newest.n,
        body: {
          ...newest.body,
          [subject.fields[0].id]:
            `${newest.body[subject.fields[0].id]} I'm calling from the Olaya branch.`,
        },
      }
      setRival(theirs)
      setSubject((current) => ({
        ...current,
        versions: [theirs, ...current.versions],
      }))
    }
    setReviewing(true)
  }

  function save() {
    const n = subject.versions[0].n + 1
    const made: Version = {
      n,
      author: "You",
      mine: true,
      at: "Just now",
      editedFrom: base,
      summary: null,
      everLive: false,
      body: draft,
    }
    setSubject((current) => ({
      ...current,
      versions: [made, ...current.versions],
    }))
    setBase(n)
    setRival(null)
    setReviewing(false)
    toast.success(`Saved as v${n}`, {
      description: live
        ? `Callers still hear v${subject.marker}.`
        : "It runs from the next call.",
    })
  }

  function discard() {
    const before = { draft, base }
    setDraft(newest.body)
    setBase(newest.n)
    toast("Changes discarded", {
      action: {
        label: "Undo",
        onClick: () => {
          setDraft(before.draft)
          setBase(before.base)
        },
      },
    })
  }

  async function publish(n: number): Promise<boolean> {
    await new Promise((resolve) => setTimeout(resolve, 900))
    if (caseId === "publish-fails") return false
    const before = { marker: subject.marker, published: subject.published }
    setSubject((current) => ({
      ...current,
      marker: n,
      published: { by: "You", at: "Just now" },
      versions: current.versions.map((version) =>
        version.n === n ? { ...version, everLive: true } : version,
      ),
    }))
    setHistory(null)
    toast.success(`v${n} is live`, {
      description:
        before.marker !== null && n < before.marker
          ? `Rolled back from v${before.marker}. No version was made.`
          : "Callers hear it from the next call.",
      action: {
        label: "Undo",
        onClick: () =>
          setSubject((current) => ({
            ...current,
            marker: before.marker,
            published: before.published,
          })),
      },
    })
    return true
  }

  function editFrom(n: number) {
    const version = subject.versions.find((item) => item.n === n)
    if (!version) return
    setBase(n)
    setDraft(version.body)
    setHistory(null)
  }

  function toggleLive(on: boolean) {
    const before = { marker: subject.marker, published: subject.published }
    setSubject((current) => ({
      ...current,
      marker: on ? current.versions[0].n : null,
      published: on ? { by: "You", at: "Just now" } : null,
      versions: on
        ? current.versions.map((version, index) =>
            index === 0 ? { ...version, everLive: true } : version,
          )
        : current.versions,
    }))
    toast(
      on ? `${subject.name} is live` : `${subject.name} is no longer live`,
      {
        description: on
          ? `v${newest.n} is the live version. Saves wait for a publish.`
          : `v${newest.n} runs from the next call. Saves apply straight away.`,
        action: {
          label: "Undo",
          onClick: () =>
            setSubject((current) => ({
              ...current,
              marker: before.marker,
              published: before.published,
            })),
        },
      },
    )
  }

  return (
    <main className="mx-auto flex w-full max-w-3xl flex-col gap-6 p-8 pb-28">
      <EditorHeader
        base={base}
        canEdit={canEdit}
        onOpenHistory={() => setHistory({ n: newest.n, against: null })}
        onToggleLive={toggleLive}
        subject={subject}
      />

      {ahead.length > 0 ? (
        <Item variant="outline">
          <ItemContent>
            <ItemTitle className="tabular-nums">
              {ahead.length === 1
                ? `v${ahead[0].n} isn’t live yet`
                : `v${ahead[ahead.length - 1].n} to v${ahead[0].n} aren’t live yet`}
            </ItemTitle>
            <ItemDescription className="tabular-nums">
              Callers hear v{subject.marker}.
            </ItemDescription>
          </ItemContent>
          <ItemActions>
            <Button
              onClick={() =>
                setHistory({ n: newest.n, against: subject.marker })
              }
            >
              Review and publish
            </Button>
          </ItemActions>
        </Item>
      ) : null}

      {editingFrom ? (
        <Alert>
          <AlertTitle className="tabular-nums">Editing from v{base}</AlertTitle>
          <AlertDescription className="tabular-nums">
            {baseVersion.author}, {baseVersion.at}. Saving makes v{newest.n + 1}{" "}
            with this content; v{newest.n} stays in history.
          </AlertDescription>
          <AlertAction>
            <Button onClick={discard} size="sm" variant="outline">
              <BackToNewestIcon />
              Back to v{newest.n}
            </Button>
          </AlertAction>
        </Alert>
      ) : null}

      <FieldGroup>
        {subject.fields.map((field) => (
          <Field key={field.id}>
            <FieldLabel htmlFor={field.id}>{field.label}</FieldLabel>
            {field.multiline ? (
              <Textarea
                dir="auto"
                disabled={!canEdit}
                id={field.id}
                onChange={(event) =>
                  setDraft((current) => ({
                    ...current,
                    [field.id]: event.target.value,
                  }))
                }
                rows={6}
                value={draft[field.id]}
              />
            ) : (
              <Input
                dir="auto"
                disabled={!canEdit}
                id={field.id}
                onChange={(event) =>
                  setDraft((current) => ({
                    ...current,
                    [field.id]: event.target.value,
                  }))
                }
                value={draft[field.id]}
              />
            )}
          </Field>
        ))}
      </FieldGroup>

      {changes > 0 ? (
        <Card className="sticky bottom-4" size="sm">
          <CardContent className="flex items-center gap-3">
            <span className="text-sm tabular-nums">
              {changes === 1 ? "1 change" : `${changes} changes`}
            </span>
            <div className="ms-auto flex items-center gap-2">
              <Button onClick={discard} variant="ghost">
                Discard
              </Button>
              <Button onClick={openReview}>Review and save</Button>
            </div>
          </CardContent>
        </Card>
      ) : null}

      <SaveReview
        base={base}
        draft={draft}
        onOpenChange={setReviewing}
        onSave={save}
        open={reviewing}
        rival={rival}
        subject={subject}
      />

      <HistoryDrawer
        canEdit={canEdit}
        caseId={caseId}
        editing={base}
        initial={history ?? { n: newest.n, against: null }}
        onEditFrom={editFrom}
        onOpenChange={(open) => {
          if (!open) setHistory(null)
        }}
        onPublish={publish}
        open={history !== null}
        subject={
          caseId === "view-only"
            ? {
                ...subject,
                versions: subject.versions.map((v) => ({ ...v, mine: false })),
              }
            : subject
        }
      />
    </main>
  )
}

/** A stand-in for the generated summary: which parts the save touched. */
function summarise(subject: Subject, version: Version) {
  const parent = subject.versions.find((item) => item.n === version.editedFrom)
  const touched = subject.fields
    .filter(
      (field) => parent && parent.body[field.id] !== version.body[field.id],
    )
    .map((field) => field.label)
  return touched.length
    ? `${touched.join(" and ")}: edited${version.editedFrom ? ` from v${version.editedFrom}` : ""}.`
    : `Same content as v${version.editedFrom}.`
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

/*
 * The line diff from the design system's Unsaved changes topic
 * (save-bar-preview.tsx), shared because three places need it: the live
 * scenario save review (DES-203), and configuration versioning's save,
 * publish and compare (DES-202). FoldedDiff, below, is the reading version
 * for history and approval: numbered, aligned, untouched lines folded.
 */

type DiffLine = { kind: "same" | "removed" | "added"; text: string }

/** Line-level diff by longest common subsequence — prompts are short. */
export function diffLines(before: string, after: string): DiffLine[] {
  const a = before.split("\n")
  const b = after.split("\n")
  const table = Array.from({ length: a.length + 1 }, () =>
    Array<number>(b.length + 1).fill(0),
  )
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      table[i][j] =
        a[i] === b[j]
          ? table[i + 1][j + 1] + 1
          : Math.max(table[i + 1][j], table[i][j + 1])

  const out: DiffLine[] = []
  let i = 0
  let j = 0
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) {
      out.push({ kind: "same", text: a[i] })
      i++
      j++
    } else if (table[i + 1][j] >= table[i][j + 1]) {
      out.push({ kind: "removed", text: a[i++] })
    } else {
      out.push({ kind: "added", text: b[j++] })
    }
  }
  while (i < a.length) out.push({ kind: "removed", text: a[i++] })
  while (j < b.length) out.push({ kind: "added", text: b[j++] })
  return out
}

const LINE = "flex gap-2 px-3 py-1 whitespace-pre-wrap"
const REMOVED = "bg-destructive-tint text-destructive-tint-foreground"
const ADDED = "bg-success-tint text-success-tint-foreground"

/** Unchanged lines stay muted; only what changed carries colour. */
export function LineDiff({ before, after }: { before: string; after: string }) {
  return (
    <div className="overflow-hidden rounded-lg border text-xs">
      {diffLines(before, after).map((line, index) => (
        <div
          key={index}
          dir="auto"
          className={cn(
            LINE,
            line.kind === "removed" && REMOVED,
            line.kind === "added" && ADDED,
            line.kind === "same" && "text-muted-foreground",
          )}
        >
          <span aria-hidden className="w-3 shrink-0 select-none">
            {line.kind === "removed" ? "−" : line.kind === "added" ? "+" : ""}
          </span>
          <span>{line.text}</span>
        </div>
      ))}
    </div>
  )
}

/**
 * The same diff as two columns — the older text on the start side, the
 * newer on the end — for comparing two versions where there is room. A line
 * that went is tinted on its side, a line that came on the other; unchanged
 * lines sit level in both so the eye can run across.
 */
export function SideBySideDiff({
  before,
  after,
}: {
  before: string
  after: string
}) {
  const lines = diffLines(before, after)
  return (
    <div className="grid grid-cols-2 overflow-hidden rounded-lg border text-xs">
      <div className="border-e">
        {lines
          .filter((line) => line.kind !== "added")
          .map((line, index) => (
            <div
              key={index}
              dir="auto"
              className={cn(
                LINE,
                line.kind === "removed" ? REMOVED : "text-muted-foreground",
              )}
            >
              {line.text}
            </div>
          ))}
      </div>
      <div>
        {lines
          .filter((line) => line.kind !== "removed")
          .map((line, index) => (
            <div
              key={index}
              dir="auto"
              className={cn(
                LINE,
                line.kind === "added" ? ADDED : "text-muted-foreground",
              )}
            >
              {line.text}
            </div>
          ))}
      </div>
    </div>
  )
}

/** How many lines a change adds and removes — the "+2 −1" on a field. */
export function diffStat(before: string, after: string) {
  const lines = diffLines(before, after)
  return {
    added: lines.filter((line) => line.kind === "added").length,
    removed: lines.filter((line) => line.kind === "removed").length,
  }
}

/** "+2 −1", each half in its own colour, zero halves muted. */
export function DiffStat({
  added,
  removed,
}: {
  added: number
  removed: number
}) {
  return (
    <span className="flex items-center gap-2 text-xs font-medium tabular-nums">
      <span className={added ? "text-success" : "text-muted-foreground"}>
        +{added}
      </span>
      <span className={removed ? "text-destructive" : "text-muted-foreground"}>
        −{removed}
      </span>
    </span>
  )
}

type Side = { text: string; n: number; changed: boolean } | null
type Row = { changed: boolean; left: Side; right: Side }

/**
 * The diff as aligned rows: an unchanged line sits level on both sides, and
 * a run of removed lines pairs off against the run of added lines that
 * replaces it, so a split view never drifts out of line.
 */
function alignedRows(before: string, after: string): Row[] {
  const rows: Row[] = []
  let oldN = 0
  let newN = 0
  let removed: Side[] = []
  let added: Side[] = []
  const flush = () => {
    for (let i = 0; i < Math.max(removed.length, added.length); i++)
      rows.push({
        changed: true,
        left: removed[i] ?? null,
        right: added[i] ?? null,
      })
    removed = []
    added = []
  }
  for (const line of diffLines(before, after)) {
    if (line.kind === "same") {
      flush()
      oldN++
      newN++
      rows.push({
        changed: false,
        left: { text: line.text, n: oldN, changed: false },
        right: { text: line.text, n: newN, changed: false },
      })
    } else if (line.kind === "removed") {
      removed.push({ text: line.text, n: ++oldN, changed: true })
    } else {
      added.push({ text: line.text, n: ++newN, changed: true })
    }
  }
  flush()
  return rows
}

/** Unified rows: removed lines then added ones, numbered on their own side. */
function unifiedRows(before: string, after: string) {
  let oldN = 0
  let newN = 0
  return diffLines(before, after).map((line) => {
    if (line.kind !== "added") oldN++
    if (line.kind !== "removed") newN++
    return {
      changed: line.kind !== "same",
      kind: line.kind,
      text: line.text,
      n: line.kind === "removed" ? oldN : newN,
    }
  })
}

/**
 * Which rows to draw: every change and `context` lines either side of it.
 * The rest fold into one "n unchanged lines" row each, which opens in place.
 */
function fold<T extends { changed: boolean }>(rows: T[], context: number) {
  const near = rows.map((_, index) =>
    rows
      .slice(Math.max(0, index - context), index + context + 1)
      .some((row) => row.changed),
  )
  const out: ({ row: T } | { hidden: T[]; id: number })[] = []
  rows.forEach((row, index) => {
    if (near[index]) {
      out.push({ row })
      return
    }
    const last = out[out.length - 1]
    if (last && "hidden" in last) last.hidden.push(row)
    else out.push({ hidden: [row], id: index })
  })
  /* Folding one line saves nothing and costs a click: show it instead. */
  return out.flatMap((piece) =>
    "hidden" in piece && piece.hidden.length === 1
      ? [{ row: piece.hidden[0] }]
      : [piece],
  )
}

const NUMBER =
  "w-7 shrink-0 text-end text-muted-foreground/60 tabular-nums select-none"

/**
 * A field's diff for reading a version: line numbers in the gutter, only
 * what changed in colour, and the untouched stretches folded so a
 * one-line change in a forty-line prompt reads as one line, not forty.
 *
 * `split` puts the older text on the start side and the newer on the end,
 * row-aligned; `unified` stacks them, − above +. `bare` drops the frame for
 * a diff that sits inside a block with its own.
 */
export function FoldedDiff({
  before,
  after,
  layout = "unified",
  context = 1,
  bare = false,
}: {
  before: string
  after: string
  layout?: "unified" | "split"
  context?: number
  bare?: boolean
}) {
  const [opened, setOpened] = React.useState<Set<number>>(new Set())
  const open = (id: number) => setOpened((current) => new Set([...current, id]))

  const frame = cn("text-xs", !bare && "overflow-hidden rounded-lg border")

  if (layout === "split") {
    const pieces = fold(alignedRows(before, after), context)
    return (
      <div className={frame}>
        {pieces.map((piece, index) =>
          "row" in piece || opened.has(piece.id) ? (
            ("row" in piece ? [piece.row] : piece.hidden).map((row, j) => (
              <div className="grid grid-cols-2" key={`${index}-${j}`}>
                <SplitCell side={row.left} tone={REMOVED} />
                <SplitCell className="border-s" side={row.right} tone={ADDED} />
              </div>
            ))
          ) : (
            <FoldRow
              count={piece.hidden.length}
              key={index}
              onOpen={() => open(piece.id)}
            />
          ),
        )}
      </div>
    )
  }

  const pieces = fold(unifiedRows(before, after), context)
  return (
    <div className={frame}>
      {pieces.map((piece, index) =>
        "row" in piece || opened.has(piece.id) ? (
          ("row" in piece ? [piece.row] : piece.hidden).map((row, j) => (
            <div
              className={cn(
                LINE,
                "ps-0",
                row.kind === "removed" && REMOVED,
                row.kind === "added" && ADDED,
                row.kind === "same" && "text-muted-foreground",
              )}
              dir="auto"
              key={`${index}-${j}`}
            >
              <span className={NUMBER}>{row.n}</span>
              <span aria-hidden className="w-3 shrink-0 select-none">
                {row.kind === "removed" ? "−" : row.kind === "added" ? "+" : ""}
              </span>
              <span>{row.text}</span>
            </div>
          ))
        ) : (
          <FoldRow
            count={piece.hidden.length}
            key={index}
            onOpen={() => open(piece.id)}
          />
        ),
      )}
    </div>
  )
}

function SplitCell({
  side,
  tone,
  className,
}: {
  side: Side
  tone: string
  className?: string
}) {
  return (
    <div
      className={cn(
        LINE,
        "ps-0",
        side?.changed ? tone : "text-muted-foreground",
        !side && "bg-muted/40",
        className,
      )}
      dir="auto"
    >
      <span className={NUMBER}>{side?.n ?? ""}</span>
      <span>{side?.text ?? ""}</span>
    </div>
  )
}

function FoldRow({ count, onOpen }: { count: number; onOpen: () => void }) {
  return (
    <div className="flex bg-muted/40 ps-8">
      <Button onClick={onOpen} size="xs" variant="ghost">
        {count === 1 ? "1 unchanged line" : `${count} unchanged lines`}
      </Button>
    </div>
  )
}

